   [60]={next_id=61, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Divinelight Heavy Tech has so many branches, and the Lavox Branch is just one of the less noticeable ones. It only caught the attention of the higher-ups because of this mountain's resources.", msg_color="", msg_size=0, talker="Nova", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7161", 0, 0, 1.5, 220}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
