   [62]={next_id=63, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I've been meaning to ask—what's the deal with the Mutant activity in these mountains? Why is it like this?", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Oh, that? There used to be a factory in the mountains, supplying materials for local research and production. A few years before I took over, there was an accident. The previous head of the branch led most of the security team to seal off the area, at a heavy cost. After that, most of them retired early.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="And then?", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The security department got filled with people who got in through connections. After all, apart from Divinelight Heavy Tech, job opportunities in Lavox are pretty limited... Oh, right, I should mention—I'm technically a connection hire too.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
