   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Back then, you'd already gone to work at Leistance. I took advantage of the personnel reshuffle and asked our teacher to put in a good word for me with the Chief Instructor. That's how I got prioritized for assignment here.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="A good word? Hmm... Maybe you've got it wrong. The Chief Instructor told me you're an outstanding AIMBS.", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Letting you come back was just because she recognized your skills. Besides, she's not the type to be easily swayed.", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
