   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Oh, that? Probably just Mutant activity in the mountains.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="That's where the factory that had the accident is. It's been years, and we still haven't fully cleared it out. Those *Lavox-expletive* Mutants—", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Poharu, when are you going to fix this habit of cursing when you're excited?!", msg_color="", msg_size=0, talker="Nova", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7161", 0, 0, 1.5, 220},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...Yeah, yeah, I'll change it!", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...The Mutants often break into the testing grounds in the mountains and sometimes even harass the town. It's been a constant headache.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Can't they be completely eradicated? Like organizing a special operation to wipe them out, clean up the contamination source, and eliminate the threat for good?", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="We've thought about it. It's in the plans. Personnel isn't the main issue—it's just that after all these years, no one knows what's really going on in there or if there are even more dangerous Mutants lurking.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [85]={next_id=86, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Besides, a small place like this doesn't have a Linker. If something goes wrong, it'd be a disaster. I've got to prioritize the safety of the department members.", msg_color="", msg_size=0, talker="Crag", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I see. Let's be careful not to get noticed.", msg_color="", msg_size=0, talker="Ling", audio="", img="arts/ui/bg/story/storybg_1403.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4504", 0, 0, 102.5, 185},{ 3, "4514", 0, 0, 53, 173}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
